// Parallel executes multiple functions concurrently and waits for all to complete.
// Example: concurrent.Parallel(task1, task2, task3)
func Parallel(tasks ...func()) {
	wg := sync.WaitGroup{}
	for _, task := range tasks {
		wg.Go(task)
	}
	wg.Wait()
}

// ParallelWithLimit executes functions with a maximum concurrency limit.
// At most `limit` functions run simultaneously. Panics on limit <= 0.
// Tasks first so an existing task list pipes: tasks |> concurrent.ParallelWithLimit(4)
// Example: concurrent.ParallelWithLimit(list of func(){task1, task2}, 4)
func ParallelWithLimit(tasks []func(), limit int) {
	wg := sync.WaitGroup{}
	sem := make(chan int, limit)
	for _, task := range tasks {
		sem <- 1
		wg.Go(func() {
			task()
			<-sem
		})
	}
	wg.Wait()
}

